import sys
from collections import defaultdict
MOD=998244353

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    vals=data[1:]
    factors=[]
    primes=set()
    for x in vals:
        d={}
        p=2
        while p*p<=x:
            while x%p==0:
                d[p]=d.get(p,0)+1
                x//=p
            p+=1
        if x>1:
            d[x]=d.get(x,0)+1
        factors.append(d)
        primes.update(d)
    answer=1
    for p in primes:
        es=[d.get(p,0) for d in factors]
        limit=sum(es)
        powers=[1]*(limit+1)
        for k in range(1,limit+1):
            powers[k]=powers[k-1]*p%MOD
        dp={0:1}
        for i,e in enumerate(es):
            nd=defaultdict(int)
            shifts=(-e,e) if e else (0,)
            for z,value in dp.items():
                for delta in shifts:
                    t=z+delta
                    if t>=0:
                        nz=t
                        contribution=powers[nz]
                    else:
                        nz=0
                        contribution=powers[(-t)*(i+1)]
                    nd[nz]=(nd[nz]+value*contribution)%MOD
            dp=nd
        answer=answer*sum(dp.values())%MOD
    print(answer)

main()

