import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    mx = max(a)

    spf = list(range(mx + 1))
    for i in range(2, int(mx ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, mx + 1, i):
                if spf[j] == j:
                    spf[j] = i

    phi = list(range(mx + 1))
    for i in range(2, mx + 1):
        if spf[i] == i:
            for j in range(i, mx + 1, i):
                phi[j] -= phi[j] // i

    divisor_cache = {}
    weighted_sums = [0] * (mx + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        divisors = divisor_cache.get(x)
        if divisors is None:
            t = x
            factors = []
            while t > 1:
                p = spf[t]
                exponent = 0
                while t % p == 0:
                    t //= p
                    exponent += 1
                factors.append((p, exponent))

            divisors = [1]
            for p, exponent in factors:
                old = divisors
                multiples = []
                power = 1
                for _ in range(exponent):
                    power *= p
                    multiples.extend(d * power for d in old)
                divisors = old + multiples
            divisor_cache[x] = divisors

        added = 0
        for d in divisors:
            added = (added + phi[d] * weighted_sums[d]) % MOD

        answer = (2 * answer + added) % MOD
        for d in divisors:
            weighted_sums[d] += weight
            if weighted_sums[d] >= MOD:
                weighted_sums[d] -= MOD

        output.append(str(answer))
        weight = weight * 2 % MOD

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

