values = list(map(int, sys.stdin.buffer.read().split()))
n = values[0]
a = values[1:]
limit = max(a)

# Smallest prime factor for every integer up to limit.
spf = list(range(limit + 1))
for p in range(2, int(limit ** 0.5) + 1):
    if spf[p] == p:
        for x in range(p * p, limit + 1, p):
            if spf[x] == x:
                spf[x] = p

# Grundy number of x is its number of prime factors, counted with multiplicity.
omega = [0] * (limit + 1)
for x in range(2, limit + 1):
    omega[x] = omega[x // spf[x]] + 1

nim_sum = 0
for x in a:
    nim_sum ^= omega[x]

print('Anna' if nim_sum else 'Bruno')

