from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))

        count = [0] * (n + 1)
        sole_id = [-1] * (n + 1)
        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0

        for right in range(1, n + 1):
            for a, idx in at[right]:
                if count[a] == 0:
                    heapq.heappush(heap, -a)
                    sole_id[a] = idx
                else:
                    sole_id[a] = -1
                count[a] += 1

            while heap and count[-heap[0]] == 0:
                heapq.heappop(heap)

            if heap:
                top = -heapq.heappop(heap)
                while heap and count[-heap[0]] == 0:
                    heapq.heappop(heap)
                second = -heap[0] if heap else 0
                heapq.heappush(heap, -top)
            else:
                top = second = 0

            base += right - top
            if top and count[top] == 1:
                gains[sole_id[top]] += top - second

        return base + max(gains)

