class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        # steps[v] is the number of popcount operations needed to reach 1.
        depth = [0] * (n + 1)
        for v in range(2, n + 1):
            depth[v] = depth[v.bit_count()] + 1
        good = [False] * (n + 1)
        for j in range(1, n + 1):
            # A number with j set bits takes one operation to become j,
            # followed by depth[j] operations to reach 1.
            good[j] = depth[j] + 1 <= k

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        invfact = [1] * (n + 1)
        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def choose(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for j in range(1, n + 1):
                    if good[j]:
                        ans += choose(rem, j - ones)
                ones += 1
        return ans % MOD

