from math import comb
class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        good = [False] * (n + 1)
        for j in range(1, n + 1):
            x = j
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[j] = steps + 1 <= k
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for j in range(1, n + 1):
                    if good[j]:
                        need = j - ones
                        if 0 <= need <= rem:
                            ans += comb(rem, need)
                ones += 1
        return ans % MOD

