            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for j in range(1, n + 1):
                    if good[j]:
                        ans += choose(rem, j - ones)
                ones += 1
        return ans % MOD

