import sys
import heapq

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = [x.decode() for x in data[1:1 + n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    for i, row in enumerate(graph):
        for j, ch in enumerate(row):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)

    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    pq = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(pq, (0, i, i))
    for i in range(n):
        for j in range(n):
            if graph[i][j] != '-':
                dist[i][j] = 1
                heapq.heappush(pq, (1, i, j))

    while pq:
        length, u, v = heapq.heappop(pq)
        if length != dist[u][v]:
            continue
        new_length = length + 2
        for c in range(26):
            xs = incoming[u][c]
            ys = outgoing[v][c]
            if not xs or not ys:
                continue
            for x in xs:
                row = dist[x]
                for y in ys:
                    if new_length < row[y]:
                        row[y] = new_length
                        heapq.heappush(pq, (new_length, x, y))

    print('\n'.join(' '.join(str(-1 if x == inf else x) for x in row) for row in dist))

solve()

