import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        adj[u] |= 1 << v
        adj[v] |= 1 << u

    rows = adj[:]
    pivots = []
    r = 0
    for c in range(n):
        pivot_row = next((i for i in range(r, n) if (rows[i] >> c) & 1), None)
        if pivot_row is None:
            continue
        rows[r], rows[pivot_row] = rows[pivot_row], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free_cols:
        vector = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vector |= 1 << c
        basis.append(vector)

    covered = 0
    for vector in basis:
        covered |= vector
    if covered != (1 << n) - 1:
        print('No')
        return

    answer = [0] * n
    for bit, vector in enumerate(basis):
        for v in range(n):
            if (vector >> v) & 1:
                answer[v] |= 1 << bit
    print('Yes')
    print(*answer)

main()

