from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]  # clockwise order
        size = n * m
        straight = [[[0] * size for _ in range(2)] for _ in range(4)]
        orders = []

        # At each cell, expected-index 0 means 2, and 1 means 0.
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            order = [r * m + c for r in rows for c in cols]
            orders.append(order)
            for x in order:
                r, c = divmod(x, m)
                nr, nc = r + dr, c + dc
                for v, value in enumerate((2, 0)):
                    if grid[r][c] == value:
                        other = 1 - v
                        if 0 <= nr < n and 0 <= nc < m:
                            straight[d][v][x] = 1 + straight[d][other][nr * m + nc]
                        else:
                            straight[d][v][x] = 1

        # best[x][v]: longest valid sequence starting at x, heading d,
        # with one clockwise turn still available.
        best = [[[0] * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            turned_dir = (d + 1) % 4
            for x in orders[d]:
                r, c = divmod(x, m)
                nr, nc = r + dr, c + dc
                for v, value in enumerate((2, 0)):
                    if grid[r][c] != value:
                        continue
                    other = 1 - v
                    length = 1
                    if 0 <= nr < n and 0 <= nc < m:
                        y = nr * m + nc
                        length += max(best[d][other][y], straight[turned_dir][other][y])
                    best[d][v][x] = length

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + best[d][0][nr * m + nc])
        return answer

