from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(a: int, b: int, first_parity: int, length: int) -> int:
            # parity 1 is odd, 0 is even
            odd_slots = (length + 1) // 2 if first_parity == 1 else length // 2
            even_slots = length - odd_slots
            if a != odd_slots or b != even_slots:
                return 0
            return fact[a] * fact[b]

        ans = []
        unused = list(range(1, n + 1))
        a, b = odds, evens
        last_parity = None
        while unused:
            for x in unused:
                p = x % 2
                na, nb = a - (p == 1), b - (p == 0)
                rem = len(unused) - 1
                if rem == 0:
                    ways = 1
                else:
                    ways = completions(na, nb, 1 - p, rem)
                if k > ways:
                    k -= ways
                else:
                    ans.append(x)
                    unused.remove(x)
                    a, b = na, nb
                    last_parity = p
                    break
            else:
                return []
        return ans

