class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        cells = m * n

        # Number of placements containing any fixed pair of cells.
        fact = [1] * (cells + 1)
        for i in range(1, cells + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (cells + 1)
        inv_fact[cells] = pow(fact[cells], MOD - 2, MOD)
        for i in range(cells, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        arrangements_per_pair = (
            fact[cells - 2] * inv_fact[k - 2] % MOD * inv_fact[cells - k] % MOD
        )

        # Sum of Manhattan distances over all unordered pairs of cells.
        distance_sum = (
            n * n * (m**3 - m) + m * m * (n**3 - n)
        ) // 6

        return (distance_sum % MOD) * arrangements_per_pair % MOD

