def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # In an optimal composition, functions are ordered by (A - 1) / B
    # from innermost to outermost.
    def compare(x, y):
        lhs = (x[0] - 1) * y[1]
        rhs = (y[0] - 1) * x[1]
        return (lhs > rhs) - (lhs < rhs)

    funcs.sort(key=cmp_to_key(compare))

    dp = [None] * (k + 1)
    dp[0] = 1
    processed = 0
    for a, b in funcs:
        processed += 1
        for count in range(min(k, processed), 0, -1):
            if dp[count - 1] is not None:
                value = a * dp[count - 1] + b
                if dp[count] is None or value > dp[count]:
                    dp[count] = value

    print(dp[k])

