class Solution:
    def makeStringGood(self, s: str) -> int:
        freq = [0] * 26
        for ch in s:
            freq[ord(ch) - ord('a')] += 1

        answer = len(s)
        for target in range(1, max(freq) + 1):
            # The state maps the number of characters passed from the
            # preceding letter to the minimum cost so far.
            dp = {0: 0}
            for i in range(26):
                next_dp = {}
                for incoming, cost in dp.items():
                    available = freq[i] + incoming
                    # Choose how many characters to change to the next letter.
                    # The remaining count at this letter is either zero or target.
                    choices = {0, available}
                    if available >= target:
                        choices.add(available - target)
                    # A partial transfer can be useful to bring the next
                    # letter's count up to target.
                    if i < 25:
                        needed = max(0, target - freq[i + 1])
                        if needed <= available:
                            choices.add(needed)

                    for outgoing in choices:
                        remaining = available - outgoing
                        # Insert or delete to leave either zero or target.
                        local = outgoing + min(remaining, abs(remaining - target))
                        # The expression above accounts for deletion to zero,
                        # or adjustment to target.
                        value = cost + local
                        if outgoing not in next_dp or value < next_dp[outgoing]:
                            next_dp[outgoing] = value
                dp = next_dp

            answer = min(answer, dp.get(0, len(s)))
        return answer

