from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for node in range(1, n):
            children[parent[node]].append(node)

        postorder = []
        start = [0] * n
        end = [0] * n
        stack = [(0, False)]
        while stack:
            u, exiting = stack.pop()
            if not exiting:
                start[u] = len(postorder)
                stack.append((u, True))
                for v in reversed(children[u]):
                    stack.append((v, False))
            else:
                postorder.append(s[u])
                end[u] = len(postorder) - 1

        t = ''.join(postorder)
        m = len(t)
        odd = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < m and t[i - k] == t[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * m
        left, right = 0, -1
        for i in range(m):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < m and t[i - k - 1] == t[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = [False] * n
        for u in range(n):
            l, r = start[u], end[u]
            length = r - l + 1
            if length & 1:
                answer[u] = odd[(l + r) // 2] >= length // 2 + 1
            else:
                answer[u] = even[(l + r + 1) // 2] >= length // 2
        return answer

