import sys
MOD = 998244353

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].decode()
    if s[0] != 'B' or s[-1] != 'W':
        print(0)
        return
    # t[b] is the greatest number of Ws in a proper prefix containing
    # exactly b Bs, before the next B (or before the end for b=N).
    t = [0] * (n + 1)
    b = w = 0
    for c in s:
        if c == 'B':
            if b:
                t[b] = w
            b += 1
        else:
            w += 1
    t[n] = n - 1  # last character is W, so the final proper prefix has N-1 Ws

    # dp[b][m]: partial injective sequences of b white indices with prefix max m.
    # The next value can be an unused value <=m (m-b choices), or a new record x>m.
    dp = [0] * (n + 1)
    dp[0] = 1
    for b in range(n):
        ndp = [0] * (n + 1)
        for m, val in enumerate(dp):
            if not val:
                continue
            if m > t[b]:
                # choose a non-record value among 1..m
                if m > b:
                    ndp[m] = (ndp[m] + val * (m - b)) % MOD
                # choose a new record x; each x is one choice
                for x in range(m + 1, n + 1):
                    ndp[x] = (ndp[x] + val) % MOD
        dp = ndp
        nb = b + 1
        for m in range(n + 1):
            if m <= t[nb]:
                dp[m] = 0
    print(sum(dp) % MOD)

if __name__ == '__main__':
    main()

