class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        answer = None

        for i, value in enumerate(nums, 1):
            prefix += value
            r = i % k
            if min_prefix[r] is not None:
                candidate = prefix - min_prefix[r]
                if answer is None or candidate > answer:
                    answer = candidate
            if min_prefix[r] is None or prefix < min_prefix[r]:
                min_prefix[r] = prefix

        return answer

