            s = list(str(x))
            res = {x}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    s[i], s[j] = s[j], s[i]
                    res.add(int(''.join(s)))
                    s[i], s[j] = s[j], s[i]
            return res

        transformed = [outcomes(x) for x in nums]
        ans = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[j] in transformed[i] or nums[i] in transformed[j]:
                    ans += 1
        return ans

