from collections import Counter

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        counts = Counter(nums)
        total = sum(nums)
        answer = None
        for outlier in counts:
            sum_value = total - outlier
            available = counts.get(sum_value, 0) - (1 if sum_value == outlier else 0)
            if available > 0:
                if answer is None or outlier > answer:
                    answer = outlier
        return answer

