from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        # For each index, dp's set bits are the sums achievable using
        # processed queries that cover that index.
        dp = [1] * n
        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] |= dp[i] << value
                dp[i] &= (1 << (nums[i] + 1)) - 1

            if all((dp[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1

