import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        low = 10 ** (digits - 1)
        limit = 10 ** digits

        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, int((limit - 1) ** 0.5) + 1):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        places = [10 ** i for i in range(digits)]
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in places:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt >= low and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

