from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        # For each i, maintain LCP(nums[i:], nums[j:]) for j > i.
        # Iterating j upward lets us update this row in place using the
        # previous row's value at j+1.
        lcp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            first_is_prefix = z[i] >= i
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    lcp[j] = lcp[j + 1] + 1
                else:
                    lcp[j] = 0
                if first_is_prefix or lcp[j] >= j - i:
                    answer += 1
        return answer

