import sys

def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    s = data[1]
    t = data[2]
    n, m = len(s), len(t)
    if abs(n - m) > 1:
        print("No")
        return
    if n == m:
        mismatches = 0
        for a, b in zip(s, t):
            if a != b:
                mismatches += 1
                if mismatches > 1:
                    print("No")
                    return
        print("Yes")
        return
    if n > m:
        s, t = t, s  # s is now the shorter string
    i = j = 0
    skipped = False
    while i < len(s) and j < len(t):
        if s[i] == t[j]:
            i += 1
            j += 1
        elif skipped:
            print("No")
            return
        else:
            skipped = True
            j += 1
    print("Yes")

if __name__ == '__main__':
    main()

