from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # Each state gives the colors of a mirrored pair of houses.
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        for i in range(1, n // 2):
            ndp = [0] * len(states)
            for x, (a, b) in enumerate(states):
                best = min(
                    dp[y]
                    for y, (c, d) in enumerate(states)
                    if a != c and b != d
                )
                ndp[x] = best + cost[i][a] + cost[n - 1 - i][b]
            dp = ndp

        return min(dp)

