class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        total = 0
        n = len(word)
        for left in range(n):
            seen = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    seen.add(ch)
                else:
                    consonants += 1
                    if consonants > k:
                        break
                if consonants == k and len(seen) == 5:
                    total += 1
        return total

